import pyomo.environ as pyo

DATA = {
    "attractions": ["X", "Y", "Z"],
    "revenue": {"X": 500, "Y": 300, "Z": 200},
    "min_tourists": {"X": 200, "Y": 150, "Z": 100},
    "capacity": 1000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["attractions"])

    model.tourists = pyo.Var(
        model.I,
        within=pyo.NonNegativeIntegers,
        bounds=(0, d["capacity"]),
    )

    def obj_rule(m):
        return sum(d["revenue"][i] * m.tourists[i] for i in m.I)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.maximize)

    def capacity_rule(m):
        return sum(m.tourists[i] for i in m.I) <= d["capacity"]

    model.capacity_limit = pyo.Constraint(rule=capacity_rule)

    def min_tourists_rule(m, i):
        return m.tourists[i] >= d["min_tourists"][i]

    model.min_tourists = pyo.Constraint(model.I, rule=min_tourists_rule)

    return model
